    }
  }
}

content.text:
/// The gh-1934 413 image-payload recovery ladder: a provider rejecting a
/// request for SIZE (`413`-class, `isPayloadTooLargeError`) never ends in
/// an unusable session. Bounded at TWO recovery passes per streamed
/// response, each refusal halving the session's adaptive image budget:
///
/// - **Pass 1** — drop the oldest images until the payload rides under
///   the halved adaptive budget (the registry's byte-budget fill; config
///   still honored when lower), and retry.
/// - **Pass 2** — halve again AND strip ALL images to `[image dropped:
///   …]` placeholders (the session-wide strip-all latch), and retry.
/// - **Exhausted** — ONE actionable failure notice (`switch provider or
///   lower images.maxBytesPerRequest`) and the provider error surfaces
///   exactly as before. No loops: the strip-all latch keeps every later
///   request of the session image-free, so neither the ladder nor a
///   compaction⇄413 cycle can re-engage on the same bytes.
///
/// Same family as the #1750 image-cap heal (a count refusal) and the
/// gh-1680 message-cap heal — this one is the SIZE refusal twin. The
/// kill switch (`images.registry: false`) and a missing
/// [AgentLoopConfig.imageRecovery] state disable the whole ladder: the
/// error surfaces as today (AC6, legacy shape).
part of 'agent_loop.dart';

/// Emitted when the gh-1934 recovery ladder ran: the request was refused
/// for SIZE, the adaptive budget was halved (and — pass 2 — every image
/// stripped to a placeholder), and the payload was rebuilt through the
/// registry. Repairs are never silent: [dropped]/[stripped] carry the
/// counts the rebuilt request rode, and [failed] marks the single
/// actionable exhaustion event.
final class ImagePayloadRecoveryEvent extends AgentEvent {
  const ImagePayloadRecoveryEvent({
    required this.pass,
    required this.dropped,
    required this.stripped,
    this.failed = false,
    this.providerError,
  });

  /// The ladder pass that ran (1 = budget drop, 2 = strip-all).
  final int pass;

  /// Images dropped by the halved adaptive budget.
  final int dropped;

  /// Image blocks stripped to `[image dropped: …]` placeholders.
  final int stripped;

  /// Whether the ladder exhausted (the provider still refuses): fired
  /// once, then the error surfaces as before.
  final bool failed;

  /// The raw provider error behind a [failed] event.
  final String? providerError;
}

/// Whether the request window carries image bytes the ladder could shed —
/// ImageContent blocks, plus the text-embedded data-URL shapes the
/// #1916 fold lifts into blocks at rewrite time (a legacy 413 session
/// must reach the ladder too). A text-only window never engages the
/// ladder (AC6).
bool _windowHasImages(List<Message> messages) {
  bool blocksHaveImages(List<ContentBlock> blocks) => blocks.any(
    (block) =>
        block is ImageContent ||
        (block is TextContent && block.text.contains('data:image/')),
  );
  for (final message in messages) {
    switch (message) {
      case UserMessage(:final content):
        if (content is String) {
          if (content.contains('data:image/')) return true;
        } else if (blocksHaveImages(content as List<ContentBlock>)) {
          return true;
        }
      case ToolResultMessage(:final content):
        if (blocksHaveImages(content)) return true;
      default:
    }
  }
  return false;
}

/// Whether a finished turn needs the gh-1934 413 recovery ladder: a
/// classified payload-size refusal on an error stop, with the recovery
/// state attached and the registry alive, before the ladder exhausted —
/// and only when the window actually carries image bytes (a text-only
/// 413 belongs to the provider, not to images).
bool _needsImage413Recovery(
  bool exhausted,
  AssistantMessage finished,
  Context context,
  AgentLoopConfig config,
) =>
    !exhausted &&
    finished.stopReason == StopReason.error &&
    imageRegistryConfig.enabled &&
    config.imageRecovery != null &&
    isPayloadTooLargeError(finished.errorMessage) &&
    _windowHasImages(context.messages);

/// The mutable gh-1934 ladder state of one streamed response: whether the
/// ladder exhausted (no more passes) and how many passes ran. Mirrors how
/// the other self-heal states stay response-local while the session-level
/// consequences (budget, strip-all latch) ride
/// [AgentLoopConfig.imageRecovery].
final class _Image413RecoveryState {
  bool exhausted = false;
  int passes = 0;

  /// Runs the ladder step when [finished] is a classified 413. Returns
  /// the retry instruction, or null when the error must surface (no
  /// recovery configured, text-only window, ladder exhausted — after
  /// emitting the ONE actionable failure event, AC4).
  Future<_AttemptResult?> healIfNeeded(
    AssistantMessage finished,
    Context context,
    AgentLoopConfig config,
    AgentEventSink emit,
  ) async {
    if (!_needsImage413Recovery(exhausted, finished, context, config)) {
      return null;
    }
    final recovery = config.imageRecovery!;
    if (passes >= 2) {
      exhausted = true;
      final event = ImageRecoveryEvent(
        pass: 2,
        dropped: 0,
        stripped: 0,
        failed: true,
        providerError: finished.errorMessage,
      );
      imageRecoveryNotice?.call(event);
      await emit(
        ImagePayloadRecoveryEvent(
          pass: 2,
          dropped: 0,
          stripped: 0,
          failed: true,
          providerError: finished.errorMessage,
        ),
      );
      return null;
    }
    passes++;
    final pass = passes;
    // Each 413 halves the adaptive budget (AC4) — pass 1 learns, pass 2
    // halves again before the strip.
    recovery.halveBudget(imageRegistryConfig.maxBytesPerRequest);
    if (pass == 2) recovery.stripAll = true;
    recovery.armNote(pass: pass);
    return _AttemptRetry(context);
  }
}

/// gh-1934: an armed 413 recovery note rides the NEXT request payload as a
/// trailing user message — the model sees why its images vanished and the
/// assistant answer can note the recovery (AC1). Payload-only; the note is
/// one-shot (consumed by this build, re-armed by the next pass).
Context _appendRecoveryNote(Context context, ImagePayloadRecoveryState? rec) {
  final note = rec?.consumeNote();
  if (note == null) return context;
  return Context(
    systemPrompt: context.systemPrompt,
    messages: [...context.messages, UserMessage.text(note)],
    tools: context.tools,
  );
}

/// Session-scoped 413 image-payload recovery state (gh-1934) — the
/// persistent half of the recovery ladder.
///
/// A provider rejecting a request for SIZE (413-class,
/// `isPayloadTooLargeError`) must never end in an unusable session. The
/// ladder in the agent loop (see `agent_loop_image_recovery.dart`) adapts
/// the payload — pass 1 drops the oldest images under an adaptive byte
/// budget, pass 2 strips ALL images to placeholders — and this state holds
/// what survives the retry: the learned per-session budget (halved on
/// every 413 — the cap is measured, never hardcoded per provider), the
/// strip-all latch, and the one-shot model-visible recovery note.
///
/// The state is HOST-OWNED session state (the same pattern as
/// `imageCapLatches`): one instance lives on the `Agent` for the session's
/// runtime, consulted by every request build and mutated by the ladder.
/// Session-scoped v1 (the ticket's open question 1 recommendation) — the
/// learned cap is runtime-only, never persisted.
library;

import 'image_registry.dart';

/// Floor for the adaptive image byte budget: halving past this point buys
/// nothing (the payload is text-dominated by then) and a zero budget would
/// disable the budget math entirely.
const int imageRecoveryBudgetFloor = 64 * 1024;

/// The canonical recovery notice line (UI + payload note share the
/// format; hosts add their own styling): `[images] recovered from 413:
/// dropped N, stripped M`.
String imageRecoveryNoticeText({required int dropped, required int stripped}) =>
    '[images] recovered from 413: dropped $dropped, stripped $stripped';

/// The actionable failure line when the ladder exhausted: the provider
/// still refuses and the session cannot shrink further on its own.
String imageRecoveryFailedText(String providerError) =>
    '[images] 413 recovery failed: the provider still rejects requests '
    '($providerError) — switch provider or lower images.maxBytesPerRequest';

/// One recovery pass, surfaced to hosts through the notice seam. [pass]
/// is the ladder step (1 = budget drop, 2 = strip-all); [failed] marks
/// the single actionable exhaustion event.
final class ImageRecoveryEvent {
  const ImageRecoveryEvent({
    required this.pass,
    required this.dropped,
    required this.stripped,
    this.failed = false,
    this.providerError,
  });

  /// The ladder pass this notice describes (1 or 2).
  final int pass;

  /// Images dropped by the adaptive budget (pass 1 semantics).
  final int dropped;

  /// Image blocks stripped to placeholders (pass 2 semantics).
  final int stripped;

  /// Whether the ladder exhausted: the provider still refuses after both
  /// passes. Fired exactly once, then the ladder stands down.
  final bool failed;

  /// The raw provider error behind a [failed] event.
  final String? providerError;
}

/// Set by hosts that surface recovery passes (the CLI prints the dim
/// transcript line + logs to fa.log). Same pattern as
/// [imageCapLearnedNotice].
typedef ImageRecoveryNotice = void Function(ImageRecoveryEvent event);

/// The active recovery reporter — wired once by the host at boot.
ImageRecoveryNotice? imageRecoveryNotice;

/// The session-scoped 413 recovery state: the adaptive budget, the
/// strip-all latch, and the one-shot recovery note. Mutated by the loop's
/// ladder, read by every request build.
final class ImagePayloadRecoveryState {
  int? _learnedByteBudget;
  bool _noteArmed = false;
  int _armedPass = 0;
  int _lastDropped = 0;
  int _lastStripped = 0;

  /// The adaptive budget the session learned from 413 refusals
  /// (halving); null before the first 413.
  int? get learnedByteBudget => _learnedByteBudget;

  /// Pass-2 latch: every image block — current message included — rides
  /// as a placeholder from now on. Once set it never clears for the
  /// session (the provider proved it cannot take image bytes).
  bool stripAll = false;

  /// Image content keys evicted by a recovery pass — they never ride
  /// again this session; every later build replaces them with the
  /// `[image dropped: …]` placeholder.
  final Set<String> evictedKeys = {};

  /// The effective image byte budget for a request build: the learned
  /// budget when it is lower than [configured] — the config value is
  /// still honored when IT is lower (AC5). A disabled configured budget
  /// (0) cannot raise the learned one, and a learned budget never sinks
  /// below [imageRecoveryBudgetFloor].
  int effectiveByteBudget(int configured) {
    final learned = _learnedByteBudget;
    if (learned == null) return configured;
    var effective =
        learned < imageRecoveryBudgetFloor ? imageRecoveryBudgetFloor : learned;
    if (configured > 0 && configured < effective) effective = configured;
    return effective;
  }

  /// One 413 arrived: halve the adaptive budget (learn the provider cap —
  /// measured, never a per-provider table). A disabled configured budget
  /// (0) seeds from the package default: the provider proved a cap
  /// exists, so the ladder must have something to halve.
  void halveBudget(int configured) {
    final base = _learnedByteBudget ??
        (configured > 0 ? configured : defaultMaxImageBytesPerRequest);
    final halved = (base / 2).floor();
    _learnedByteBudget = halved < imageRecoveryBudgetFloor
        ? imageRecoveryBudgetFloor
        : halved;
  }

  /// Records what one request build did with the images (called from the
  /// rewrite path on every build while the state is attached), so an
  /// armed note renders with the CURRENT build's counts.
  void observeBuild({required int dropped, required int stripped}) {
    _lastDropped = dropped;
    _lastStripped = stripped;
  }

  /// Arms the model-visible recovery note for the NEXT request build —
  /// the retried request carries it, so the assistant answer can note the
  /// recovery (AC1).
  void armNote({required int pass}) {
    _noteArmed = true;
    _armedPass = pass;
  }

  /// Whether a note is armed (the ladder checks before retrying).
  bool get noteArmed => _noteArmed;

  /// The pass the armed note belongs to.
  int get armedPass => _armedPass;

  /// Renders + disarms the armed note (null when nothing is armed).
  /// Fires the host notice seam exactly once per pass with the same
  /// counts the payload note carries.
  String? consumeNote() {
    if (!_noteArmed) return null;
    _noteArmed = false;
    imageRecoveryNotice?.call(
      ImageRecoveryEvent(
        pass: _armedPass,
        dropped: _lastDropped,
        stripped: _lastStripped,
      ),
    );
    return '${imageRecoveryNoticeText(
      dropped: _lastDropped,
      stripped: _lastStripped,
    )} — the request exceeded the provider size limit; the dropped images '
        'are gone from this and later requests. Continue without them and '
        'treat them as unavailable.';
  }
}

  final bool? reliefUsed;

  /// The issue #85 pairing heal's one-shot flag when the retry came from
  /// the pairing self-heal; null = unchanged.
  final bool? pairingHealed;
}

/// The finished-turn self-heals of one streamed attempt: the gh-1680
/// message-cap heal runs FIRST (it may replace the context via the
/// host's relief pass), then the issue #85 pairing heal. Returns null
/// when no heal applied (the caller surfaces the finished turn), else
/// the retry/terminal instruction to act on. Extracted from
/// [_streamAttempt] so the branch handling does not ride in the loop.
Future<_AttemptResult?> _finishedTurnResult(
  AssistantMessage finished,
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  CancelToken? cancelToken,
  _CapHealState capState,
  _ImageCapHealState imageCapState,
  _Image413RecoveryState image413State,
  bool pairingHealed,
  int refusedCount,
) async {
  // Issue #1750 self-healing retry: an image-count 400 means the request
  // carried more unique images than the model accepts — latch the
  // learned cap and retry ONCE; the retry rebuilds through the registry
  // at the smaller cap (the drops ride the existing cap-drop notices,
  // never silent). A second refusal surfaces the terminal error (AC4).
  if (imageCapState.healIfNeeded(finished, config)) {
    return _AttemptRetry(context);
  }
  // gh-1934 self-healing ladder: a 413 payload-size refusal means the
  // request's image bytes exceeded the provider's real cap — halve the
  // session's adaptive budget (pass 1), then strip ALL images (pass 2),
  // retrying through the registry; bounded, never a bricked session.
  final image413 = await image413State.healIfNeeded(
    finished,
    context,
    config,
    emit,
  );
  if (image413 != null) return image413;
  // gh-1680 self-healing retry: a message-cap 400 means the message
  // ARRAY passed the model's per-request cap — learn, compact +
  // coalesce, retry ONCE (a second refusal is terminal; see the part).
  final capHeal = await capState.healIfNeeded(
    finished,
    context,
    config,
    emit,
    cancelToken,
    refusedCount,
  );
  if (capHeal.terminal != null) return _AttemptReturn(capHeal.terminal!);
  if (capHeal.ran) {
    return _AttemptRetry(capHeal.context ?? context);
  }
  // Self-healing retry (issue #85): a provider pairing 400 means the
  // context was corrupted in a shape this repairer missed. Log the
  // detection, re-run the repair over the rebuilt request, retry ONCE —
  // a wedged session recovers here instead of never. A second failure
  // surfaces normally (no infinite loop).
  if (_needsPairingHeal(pairingHealed, finished)) {
    await emit(
      ToolPairingRepairEvent(
        report: const ToolPairingRepairReport(),
        providerError: finished.errorMessage,
      ),
    );
    return _AttemptRetry(context, pairingHealed: true);
  }
  return null;
}

/// One attempt of [_streamAssistantResponse]'s retry loop: builds the
/// request context (pairing repair + armed notes + cap coalesce), runs
/// the mid-turn over-window guard, streams the response, and applies the
/// finished-turn self-heals. Returns the turn to surface to the caller,
/// or a retry instruction for the loop to adopt.
Future<_AttemptResult> _streamAttempt(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  StreamFunction streamFunction,
  CancelToken? cancelToken, {
  required String? misuseNote,
  required _CapHealState capState,
  required _ImageCapHealState imageCapState,
  required _Image413RecoveryState image413State,
  required bool reliefUsed,
  required bool pairingHealed,
  required _StreamProgress progress,
}) async {
  final (requestContext, repairReport) = await _buildRequestContext(
    context,
    config,
    cancelToken,
    misuseNote: misuseNote,
    capCoalesceTarget: capState.coalesceTarget,
    imageCapOverride: imageCapState.overrideFor(config),
    recovery: config.imageRecovery,
  );
  // Pairing repairs are always surfaced (issue #85): hosts see exactly
  // what was dropped/synthesized/renamed before the request went out.
  if (repairReport.isNotEmpty) {
    await emit(ToolPairingRepairEvent(report: repairReport));
  }

  // Mid-turn over-window guard (issue #387): tool outputs can balloon one
  // turn far past the model window. The cheap window check runs
  // SYNCHRONOUSLY and only an actual overflow awaits
  // [_overWindowGuardTurn] — an unconditional await here yields a
  // microtask on EVERY turn, which reshuffles host event-listener
  // interleaving downstream (issue #1085 CI: the flutter service's
  // persist passes lost the final assistant append). Same shape, no
  // yield on the normal path.
  final window = effectiveContextWindow(
    config.model.contextWindow,
    config.contextWindowCap,
  );
  final tokens = estimateRequestTokens(
    requestContext.messages,
    systemPrompt: requestContext.systemPrompt,
    tools: requestContext.tools ?? const [],
  );
  if (window > 0 && tokens > window) {
    final guard = await _overWindowGuardTurn(
      context,
      requestContext,
      config,
      emit,
      reliefUsed,
      cancelToken,
      window,
      tokens,
    );
    if (guard.terminal != null) return _AttemptReturn(guard.terminal!);
    if (guard.retried) {
      return _AttemptRetry(guard.context, reliefUsed: guard.reliefUsed);
    }
  }

  // gh-1680: refused payload count, captured BEFORE the stream.
  final requestMessageCount = requestContext.messages.length;

  await emit(_captureRequest(config, requestContext));
  final AssistantMessageEventStream response;
  try {
    response = streamFunction(
      config.model,
      requestContext,
      cancelToken: cancelToken,
    );
  } catch (error) {
    return _AttemptReturn(
      await _providerErrorTurn(context, config, emit, error),
    );
  }

  final streamed = await _consumeResponseStream(
    response,
    context,
    emit,
    progress,
  );
  final finished = streamed.finished;
  if (finished != null) {
    final healed = await _finishedTurnResult(
      finished,
      context,
      config,
      emit,
      cancelToken,
      capState,
      imageCapState,
      image413State,
      pairingHealed,
      requestMessageCount,
    );

    ),
    context,
  );
}

/// Builds the synthetic error turn for a provider stream that closed
/// without any terminal event (provider bug): keep the streamed partial
/// when one landed, otherwise synthesize an empty error message.
AssistantMessage _streamEndedWithoutTerminal(
  AgentLoopConfig config,
  AssistantMessage? partial,
) {
  const errorText = 'Provider stream ended without a terminal event';
  return (partial ??
          _terminalMessage(config.model, StopReason.error, errorText))
      .copyWith(stopReason: StopReason.error, errorMessage: errorText);
}

