  final current = _claimCurrentBatch(
    currentRideable,
    entryByKey,
    cap,
    maxBytes,
  );
  final historyKeys = _recencyOrderedHistoryKeys(
    entryByKey,
    occurrences,
    exclude: {...current.ride, ...current.droppedKeys, ...evicted},
