        ImageDropEvent(
          index: entryByKey[key]!.index,
          key: key,
          fromCurrentMessage: true,
          reason: _dropReason(overCount: overCount, overBytes: overBytes),
        ),
      );
      continue;
    }
    ride.add(key);
    if (maxBytes > 0) remaining -= size;
