import 'dart:async';
import 'dart:io';

// Polarity probe for the gh-1934 round-4 flutter_app teardown fix:
// the OLD fixture teardown (one-shot `tmp.delete(recursive: true)`) against
// the same late-writer shape the regression test uses.
Future<void> main() async {
  final dir = await Directory.systemTemp.createTemp('fa_race_probe');
  File('${dir.path}/seed.jsonl').writeAsStringSync('seed\n');
  final writer = Timer.periodic(const Duration(milliseconds: 8), (t) {
    if (t.tick > 10) {
      t.cancel();
      return;
    }
    final sub = Directory('${dir.path}/late-${t.tick}')
      ..createSync(recursive: true);
    File('${sub.path}/append.jsonl').writeAsStringSync('late\n');
  });
  Object? thrown;
  try {
    dir.deleteSync(recursive: true); // the OLD one-shot teardown
  } on FileSystemException catch (e) {
    thrown = e;
  }
  await Future<void>.delayed(const Duration(milliseconds: 150));
  writer.cancel();
  final survived = dir.existsSync();
  if (survived) dir.deleteSync(recursive: true);
  stdout.writeln('one-shot threw: ${thrown != null}'
      ' (${thrown is FileSystemException ? thrown.osError?.errorCode : '-'})');
  stdout.writeln('tree survived the one-shot delete: $survived');
}
